3	import { redirect } from "next/navigation";
4	import { requireRole } from "@/lib/auth";
5	import { createClient } from "@/lib/supabase/server";
6	import { getApprovedProvider } from "@/lib/db/queries";
7	import { getPayments } from "@/lib/integrations/payments";
8	import { priceForBlock } from "@/lib/pricing";
9	import { bookingCreateSchema, type BookingCreateInput } from "@/lib/validation/schemas";
10	
11	export interface BookingResult {
12	  error?: string;
13	  fieldErrors?: Record<string, string>;
14	}
15	
16	/**
17	 * Create a booking and authorise the block-price hold (mock payments). Flow:
18	 * validate → create booking (pending) → payments.authorizeHold → confirm
19	 * booking with the payment ref. Capture happens at session end (M6).
20	 */
21	export async function createBooking(
22	  input: BookingCreateInput,
23	): Promise<BookingResult> {
24	  const profile = await requireRole("customer");
25	
26	  const parsed = bookingCreateSchema.safeParse(input);
27	  if (!parsed.success) {
28	    const fieldErrors: Record<string, string> = {};
29	    for (const issue of parsed.error.issues) {
30	      const key = String(issue.path[0] ?? "");
31	      if (key && !fieldErrors[key]) fieldErrors[key] = issue.message;
32	    }
33	    return { error: "Please check your booking details.", fieldErrors };
34	  }
35	  const d = parsed.data;
36	
37	  const provider = await getApprovedProvider(d.providerId);
38	  if (!provider) return { error: "This listener isn't available right now." };
39	
40	  const priceBlockCents = priceForBlock(provider, d.blockMinutes);
41	  const supabase = await createClient();
42	
43	  const { data: booking, error: insErr } = await supabase
44	    .from("bookings")
45	    .insert({
46	      customer_id: profile.id,
47	      provider_id: provider.id,
48	      slot_id: d.slotId ?? null,
49	      block_minutes: d.blockMinutes,
50	      start_mode: d.startMode,
51	      scheduled_at: d.scheduledAt ?? null,
52	      price_block_cents: priceBlockCents,
53	      overage_per_min_cents: provider.overage_per_min_cents,
54	      status: "pending",
55	    })
56	    .select("id")
57	    .single();
58	
59	  if (insErr || !booking) {
60	    return { error: "We couldn't start your booking. Please try again." };
61	  }
62	
63	  const payments = getPayments();
64	  const { customerRef } = await payments.ensureCustomer(profile.id);
65	  const hold = await payments.authorizeHold({
66	    bookingId: booking.id,
67	    amountCents: priceBlockCents,
68	    customerRef,
69	  });
70	
71	  const { error: updErr } = await supabase
72	    .from("bookings")
73	    .update({ status: "confirmed", payment_ref: hold.paymentRef })
74	    .eq("id", booking.id);
75	
76	  if (updErr) {
77	    return { error: "We couldn't confirm your booking. Please try again." };
78	  }
79	
80	  redirect(`/account?booked=${booking.id}`);
81	}
