65	export function createMockPayments(db: Db): PaymentsProvider {
66	  return {
67	    async ensureCustomer(userId) {
68	      return { customerRef: mockRef.customer(userId) };
69	    },
70	
71	    async authorizeHold({ bookingId, amountCents, customerRef }) {
72	      const paymentRef = mockRef.payment();
73	      const { error } = await db.from("payments").insert({
74	        booking_id: bookingId,
75	        customer_id: customerIdFromRef(customerRef),
76	        amount_cents: amountCents,
77	        status: "authorized",
78	        payment_ref: paymentRef,
79	      });
80	      if (error) throw new Error(`mock authorizeHold failed: ${error.message}`);
81	      return { paymentRef, status: "authorized" };
82	    },
83	
84	    async capture({ paymentRef, amountCents }) {
85	      const { error } = await db
86	        .from("payments")
87	        .update({ status: "captured", amount_cents: amountCents })
88	        .eq("payment_ref", paymentRef);
89	      if (error) throw new Error(`mock capture failed: ${error.message}`);
90	      return { status: "captured" };
91	    },
92	
93	    async refund({ paymentRef }) {
94	      const { error } = await db
95	        .from("payments")
96	        .update({ status: "refunded" })
97	        .eq("payment_ref", paymentRef);
98	      if (error) throw new Error(`mock refund failed: ${error.message}`);
99	      return { status: "refunded" };
100	    },
101	
102	    async ensureConnectedAccount(providerId) {
103	      return { accountRef: mockRef.account(providerId) };
104	    },
105	
106	    async recordProviderEarning() {
107	      // No-op in mock: a session's provider_earnings_cents is written when the
108	      // session completes; runWeeklyPayouts aggregates from there.
109	    },
110	
111	    async runWeeklyPayouts(period) {
112	      const end = period?.periodEnd ?? new Date().toISOString();
113	      const start =
114	        period?.periodStart ??
115	        new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
116	
117	      const { data: sessions, error: sErr } = await db
118	        .from("sessions")
119	        .select("provider_id, provider_earnings_cents")
120	        .eq("status", "completed")
121	        .gte("ended_at", start)
122	        .lte("ended_at", end);
123	      if (sErr) throw new Error(`mock payouts (sessions): ${sErr.message}`);
124	
125	      const { data: tips, error: tErr } = await db
126	        .from("reviews")
127	        .select("provider_id, tip_cents")
128	        .gt("tip_cents", 0)
129	        .gte("created_at", start)
130	        .lte("created_at", end);
131	      if (tErr) throw new Error(`mock payouts (tips): ${tErr.message}`);
132	
133	      const payouts = aggregateEarnings(sessions ?? [], tips ?? []);
134	
135	      if (payouts.length > 0) {
136	        const { error: iErr } = await db.from("payouts").insert(
137	          payouts.map((p) => ({
138	            provider_id: p.providerId,
139	            period_start: start,
140	            period_end: end,
141	            amount_cents: p.amountCents,
142	            status: "scheduled" as const,
143	            scheduled_for: end,
144	          })),
145	        );
146	        if (iErr) throw new Error(`mock payouts (insert): ${iErr.message}`);
147	      }
148	
149	      return { payouts };
150	    },
151	  };
152	}
